using System.Diagnostics;
using System.Net;
using System.Net.Sockets;
using System.Reflection;
using System.Runtime.InteropServices;
using System.Text;
using System.Text.Json;
using System.Windows;
using YoWidgets;

static class NativeControlChecks
{
    internal static void Run()
    {
        var root=Path.GetFullPath("artifacts/native-control/run-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
        var chrome=new[]{Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),"Google/Chrome/Application/chrome.exe"),Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Google/Chrome/Application/chrome.exe")}.FirstOrDefault(File.Exists)??throw new Exception("Chrome fixture runtime missing");
        var app=new App {ShutdownMode=ShutdownMode.OnExplicitShutdown};typeof(App).GetProperty(nameof(App.DataRoot))!.SetValue(null,root);Ui.Theme();Exception? failure=null;
        app.Startup+=async(_,_)=> {
            nint ownedWindow=0;using var server=new HttpListener();using var lifetime=new CancellationTokenSource(TimeSpan.FromSeconds(80));
            try {
                using var portProbe=new TcpListener(IPAddress.Loopback,0);portProbe.Start();var port=((IPEndPoint)portProbe.LocalEndpoint).Port;portProbe.Stop();var url="http://127.0.0.1:"+port+"/";server.Prefixes.Add(url);server.Start();var gameEvents=new System.Collections.Concurrent.ConcurrentQueue<string>();var eventTimes=new System.Collections.Concurrent.ConcurrentDictionary<string,long>();var applied=new TaskCompletionSource<string>(TaskCreationOptions.RunContinuationsAsynchronously);
                var html="<html><head><title>YoWidgets owned browser fixture</title></head><body style='padding:40px;font:20px Arial'><h1>Owned control fixture</h1><label>Fixture input <input id='input' aria-label='Fixture input' value='seed' style='font:20px Arial;padding:12px'></label><button style='margin:20px;padding:14px' onclick=\"fetch('/applied?text='+encodeURIComponent(document.getElementById('input').value)).then(()=>document.getElementById('status').textContent='Applied')\">Apply fixture</button><p id='status'>Waiting</p><div aria-label='Game fixture' role='button' tabindex='0' onclick='this.focus()' style='height:100px;background:#bde'>Game fixture</div><script>document.oncontextmenu=e=>{e.preventDefault();fetch('/game?kind=right')};document.onkeydown=e=>{if(e.target.getAttribute('aria-label')==='Game fixture'){e.preventDefault();fetch('/game?kind=down-'+e.code)}};document.onkeyup=e=>fetch('/game?kind=up-'+e.code);</script><div style='height:2500px'>Scroll fixture</div></body></html>";
                var serve=Task.Run(async()=> {try{while(!lifetime.IsCancellationRequested){var ctx=await server.GetContextAsync().WaitAsync(lifetime.Token);if(ctx.Request.Url!.AbsolutePath=="/game"){var kind=ctx.Request.QueryString["kind"]??"";gameEvents.Enqueue(kind);eventTimes[kind]=Stopwatch.GetTimestamp();}if(ctx.Request.Url!.AbsolutePath=="/applied")applied.TrySetResult(ctx.Request.QueryString["text"]??"");var bytes=Encoding.UTF8.GetBytes(ctx.Request.Url.AbsolutePath=="/"?html:"OK");ctx.Response.ContentType="text/html; charset=utf-8";ctx.Response.ContentLength64=bytes.Length;await ctx.Response.OutputStream.WriteAsync(bytes,lifetime.Token);ctx.Response.Close();}}catch(Exception e) when(e is OperationCanceledException or HttpListenerException or ObjectDisposedException){} });
                var fixtureApp=new ApplicationLaunch("owned-chrome","Owned Chrome fixture",chrome,["--user-data-dir="+Path.Combine(root,"chrome-fixture"),"--no-first-run","--no-default-browser-check","--new-window",url]);
                using(var deniedSession=new AgentControlSession("Fixture model",()=>{},lifetime.Token)) {var deniedDesktop=new DesktopAgentTools((_,_,_)=>Task.FromResult(false),deniedSession,new InstalledApplications([fixtureApp]));bool denied=false;try{await deniedDesktop.OpenApp(fixtureApp.Id,lifetime.Token);}catch(InvalidOperationException){denied=true;}if(!denied)throw new Exception("Denied app launch ran");}
                var launcher=new DesktopAgentTools((_,_,_)=>Task.FromResult(true),null,new InstalledApplications([fixtureApp]));var launchResult=JsonSerializer.SerializeToElement(await launcher.OpenApp(fixtureApp.Id,lifetime.Token));ownedWindow=(nint)long.Parse(launchResult.GetProperty("window_id").GetString()!);if(!launchResult.GetProperty("ready").GetBoolean())throw new Exception("Launcher returned before the app was ready");
                Console.WriteLine("PASS native app launcher: denied launch blocked, actual installed executable started and real ready window returned");
                var native=new NativeBrowserTabs();BrowserTab? tab=null;for(var i=0;i<20;i++){await Task.Delay(300,lifetime.Token);await native.RefreshAsync();tab=native.Tabs.FirstOrDefault(t=>t.Title=="YoWidgets owned browser fixture");if(tab!=null)break;}
                if(tab==null)throw new Exception("Windows did not expose the owned Chrome tab");ownedWindow=(nint)long.Parse(native.WindowId(tab.Id));var attached=await native.AuthorizeAsync(tab);if(attached.Url!=url||await native.VerifyAsync(tab.Id,lifetime.Token)!=url)throw new Exception("Native attached URL mismatch");Console.WriteLine("PASS native tabs: real Chrome metadata, explicit tab selection and verified attached address");
                var approvals=0;Task<bool> Approve(string _,string __,CancellationToken ___){approvals++;return Task.FromResult(true);}
                using var lease=new CancellationTokenSource();using var session=new AgentControlSession("Fixture model",lease.Cancel,lease.Token);var desktop=new DesktopAgentTools(Approve,session);
                async Task<JsonElement> Inspect(){var result=await desktop.Inspect(new("inspect","computer_inspect",JsonSerializer.SerializeToElement(new{window_id=ownedWindow.ToInt64().ToString()})),lifetime.Token,true);return JsonSerializer.Deserialize<JsonElement>(result.Text);}
                (double X,double Y) Point(JsonElement page,string name){var node=page.GetProperty("controls").EnumerateArray().First(n=>n.GetProperty("name").GetString()==name&&n.GetProperty("width").GetDouble()>0);return(node.GetProperty("x").GetDouble()+node.GetProperty("width").GetDouble()/2,node.GetProperty("y").GetDouble()+node.GetProperty("height").GetDouble()/2);}
                ShowWindow(ownedWindow,6);await Task.Delay(150,lifetime.Token);var listed=JsonSerializer.SerializeToElement(desktop.List());if(!listed.GetProperty("windows").EnumerateArray().Any(w=>w.GetProperty("id").GetString()==ownedWindow.ToInt64().ToString()&&w.GetProperty("minimized").GetBoolean()))throw new Exception("Minimized app was omitted");
                var first=await Inspect();if(IsIconic(ownedWindow))throw new Exception("Inspection did not restore the app");Console.WriteLine("PASS native focus: minimized app is discoverable and restored before inspection/input");var point=Point(first,"Fixture input");var staleId=first.GetProperty("snapshot_id").GetString();await desktop.Act("computer_fill",JsonSerializer.SerializeToElement(new{snapshot_id=staleId,x=point.X,y=point.Y,text="Visible Unicode · тест"}),lifetime.Token);
                var next=await Inspect();point=Point(next,"Apply fixture");await desktop.Act("computer_click",JsonSerializer.SerializeToElement(new{snapshot_id=next.GetProperty("snapshot_id").GetString(),x=point.X,y=point.Y}),lifetime.Token);
                var actual=await applied.Task.WaitAsync(TimeSpan.FromSeconds(5),lifetime.Token);if(actual!="Visible Unicode · тест"||approvals!=1)throw new Exception("Actual desktop input or task consent lease failed");
                bool stale=false;try{await desktop.Act("computer_click",JsonSerializer.SerializeToElement(new{snapshot_id=staleId,x=point.X,y=point.Y}),lifetime.Token);}catch(InvalidOperationException){stale=true;}if(!stale)throw new Exception("Stale desktop snapshot accepted");
                var game=await Inspect();var gamePoint=Point(game,"Game fixture");await desktop.Act("computer_click",JsonSerializer.SerializeToElement(new{snapshot_id=game.GetProperty("snapshot_id").GetString(),x=gamePoint.X,y=gamePoint.Y}),lifetime.Token);
                game=await Inspect();await desktop.Act("computer_mouse",JsonSerializer.SerializeToElement(new{snapshot_id=game.GetProperty("snapshot_id").GetString(),x=gamePoint.X,y=gamePoint.Y,button="right"}),lifetime.Token);
                game=await Inspect();await desktop.Act("computer_press",JsonSerializer.SerializeToElement(new{snapshot_id=game.GetProperty("snapshot_id").GetString(),key="Q",duration_ms=160}),lifetime.Token);
                await LiveVoiceChecks.Until(()=>gameEvents.Contains("right")&&gameEvents.Contains("down-KeyQ")&&gameEvents.Contains("up-KeyQ"));
                if(Stopwatch.GetElapsedTime(eventTimes["down-KeyQ"],eventTimes["up-KeyQ"]).TotalMilliseconds<130)throw new Exception("Physical key hold was not applied");
                foreach(var key in new[]{"W","SPACE","CTRL+R","F1"}){game=await Inspect();await desktop.Act("computer_press",JsonSerializer.SerializeToElement(new{snapshot_id=game.GetProperty("snapshot_id").GetString(),key,duration_ms=30}),lifetime.Token);}
                game=await Inspect();using(var interrupted=new CancellationTokenSource()){interrupted.CancelAfter(120);bool released=false;try{await desktop.Act("computer_press",JsonSerializer.SerializeToElement(new{snapshot_id=game.GetProperty("snapshot_id").GetString(),key="E",duration_ms=1800}),interrupted.Token);}catch(OperationCanceledException){released=true;}if(!released)throw new Exception("Held game input did not cancel");}
                await LiveVoiceChecks.Until(()=>gameEvents.Contains("down-KeyE")&&gameEvents.Contains("up-KeyE")&&gameEvents.Contains("down-Space")&&gameEvents.Contains("up-KeyW")&&gameEvents.Contains("down-F1")&&gameEvents.Contains("up-F1"));
                foreach(var invalid in new[]{new{key="WIN",duration_ms=0},new{key="ALT+TAB",duration_ms=0},new{key="CTRL+ESC",duration_ms=0},new{key="Q",duration_ms=2001}}){game=await Inspect();bool blocked=false;try{await desktop.Act("computer_press",JsonSerializer.SerializeToElement(new{snapshot_id=game.GetProperty("snapshot_id").GetString(),invalid.key,invalid.duration_ms}),lifetime.Token);}catch(InvalidOperationException){blocked=true;}if(!blocked)throw new Exception("Unbounded/system game key accepted");}
                Console.WriteLine("PASS game input fixture: actual right mouse, physical Q/W/Space/Ctrl+R/F1, measured hold, cancellation key-up and rejected system shortcuts/long holds; no real game was launched");
                var final=await Inspect();await desktop.Act("computer_scroll",JsonSerializer.SerializeToElement(new{snapshot_id=final.GetProperty("snapshot_id").GetString(),x=final.GetProperty("width").GetDouble()*.75,y=final.GetProperty("height").GetDouble()*.75,delta=-600}),lifetime.Token);
                Console.WriteLine("PASS native control: actual smooth cursor, Unicode fill, button click, wheel input, single task consent and stale snapshot rejection in isolated Chrome fixture");
                using(var stopped=new CancellationTokenSource()){stopped.Cancel();bool cancelled=false;try{await desktop.Inspect(new("cancelled","computer_inspect",JsonSerializer.SerializeToElement(new{window_id=ownedWindow.ToInt64().ToString()})),stopped.Token);}catch(OperationCanceledException){cancelled=true;}if(!cancelled)throw new Exception("Cancelled inspection ran");}
                Console.WriteLine("PASS native control: cancellation prevents a new inspection");session.Stop();
            }catch(Exception e){Console.WriteLine(e);failure=e;}finally {lifetime.Cancel();server.Stop();if(ownedWindow!=0)PostMessage(ownedWindow,0x10,0,0);app.Shutdown();}
        };app.Run();if(failure!=null)throw failure;
    }
    [DllImport("user32.dll")] static extern bool PostMessage(nint hwnd,uint message,nint w,nint l);
    [DllImport("user32.dll")] static extern bool ShowWindow(nint hwnd,int command);
    [DllImport("user32.dll")] static extern bool IsIconic(nint hwnd);
}
